"use client";

import { useEffect, useState } from "react";
import {
  supported,
  getVoices,
  onVoicesChanged,
  speak,
  cancel,
} from "../lib/tts";

export default function TTSWidget() {
  const [text, setText] = useState("Hello! This is the homepage TTS widget.");
  const [voices, setVoices] = useState([]);
  const [voiceIndex, setVoiceIndex] = useState(0);
  const [rate, setRate] = useState(1);

  useEffect(() => {
    if (!supported) return;
    const off = onVoicesChanged((v) => {
      setVoices(v);
      if (v.length && voiceIndex >= v.length) setVoiceIndex(0);
    });
    return () => off();
  }, [voiceIndex]);

  if (!supported) {
    return (
      <div className="rounded-md bg-white/80 p-4 shadow">
        <p>Your browser does not support speech synthesis.</p>
      </div>
    );
  }

  const selectedVoice = voices[voiceIndex] || null;

  return (
    <div className="rounded-lg bg-white/80 p-4 shadow">
      <h2 className="text-lg font-semibold mb-2">Text to Speech</h2>
      <textarea
        className="w-full p-2 border rounded mb-3 text-black"
        rows={3}
        value={text}
        onChange={(e) => setText(e.target.value)}
      />
      <div className="grid grid-cols-2 gap-3 mb-3">
        <div>
          <label className="block text-sm mb-1">Voice</label>
          <select
            className="w-full p-2 border rounded text-black"
            value={voiceIndex}
            onChange={(e) => setVoiceIndex(parseInt(e.target.value, 10))}
          >
            {voices.map((v, i) => (
              <option key={v.voiceURI || i} value={i}>
                {v.name} {v.lang ? `(${v.lang})` : ""}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="block text-sm mb-1">Rate: {rate.toFixed(1)}</label>
          <input
            className="w-full"
            type="range"
            min={0.5}
            max={2}
            step={0.1}
            value={rate}
            onChange={(e) => setRate(parseFloat(e.target.value))}
          />
        </div>
      </div>
      <div className="flex gap-2">
        <button
          className="px-3 py-2 rounded bg-blue-600 text-white hover:bg-blue-700"
          onClick={() => speak({ text, voice: selectedVoice, rate })}
        >
          Speak
        </button>
        <button
          className="px-3 py-2 rounded bg-gray-200 text-black hover:bg-gray-300"
          onClick={() => cancel()}
        >
          Stop
        </button>
      </div>
    </div>
  );
}
